const FeedbackContext = createContext();

const FeedbackProvider = (props) => {
  const [feedbackData, setFeedbackData] = useState({});

  const updateFeedbackData = (newData) => {
    setFeedbackData((prevData) => ({ ...prevData, ...newData }));
  };

  return (
    <FeedbackContext.Provider value={{ feedbackData, updateFeedbackData }}>
      {props.children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
```
